
-- Batch 5: Asian recipes + European recipes
UPDATE recipes SET continent = 'Asia', history = 'Egg Rolls are a Chinese-American invention that evolved from traditional spring rolls brought by Chinese immigrants to the United States. While the original spring roll dates back to the Jin Dynasty (265-420 AD), the thicker-skinned egg roll emerged in American Chinese restaurants in the early 20th century.' WHERE slug = 'egg-rolls-cn';

UPDATE recipes SET continent = 'Asia', history = 'Chicken Satay originates from Java, Indonesia, and has spread across Southeast Asia. Inspired by Middle Eastern kebabs brought by Arab traders, Indonesians adapted the concept with local peanut sauce and spices. Satay is now considered one of Indonesia''s national dishes and a UNESCO-listed culinary heritage.' WHERE slug = 'chicken-satay-id';

UPDATE recipes SET continent = 'Asia', history = 'Butter Chicken (Murgh Makhani) was created in Delhi in the 1950s by Kundan Lal Gujral at the Moti Mahal restaurant. Born from leftover tandoori chicken mixed with a tomato, butter, and cream sauce, it became one of India''s most iconic exports and is now beloved worldwide.' WHERE slug = 'butter-chicken-in';

UPDATE recipes SET continent = 'Asia', history = 'Cauliflower Tikka is a vegetarian adaptation of the classic Indian tandoor cooking tradition. The tikka style of marinating and roasting in a clay oven dates back to the Mughal Empire (16th-19th century). This modern version reflects India''s deep vegetarian traditions, where creative plant-based cooking has flourished for millennia.' WHERE slug = 'cauliflower-tikka-in';

UPDATE recipes SET continent = 'Asia', history = 'Chicken Tikka Masala is one of the world''s most popular dishes, with disputed origins claimed by both Britain and India. Some credit a Bangladeshi chef in Glasgow in the 1970s who added tomato cream sauce to tandoori chicken. Others trace it to Punjab. Regardless, it bridges Indian and British culinary traditions.' WHERE slug = 'chicken-tikka-masala-in';

UPDATE recipes SET continent = 'Asia', history = 'Paneer Tikka is a beloved North Indian vegetarian dish where cubes of paneer cheese are marinated in spiced yogurt and grilled in a tandoor oven. Paneer itself has been produced in the Indian subcontinent for centuries, and the tandoor cooking tradition dates to the Indus Valley Civilization around 3000 BCE.' WHERE slug = 'paneer-tikka-in';

UPDATE recipes SET continent = 'Asia', history = 'Samosa Bites originated in the Middle East as "sanbosag" before traveling to India via Central Asian trade routes in the 13th-14th century. Indian samosas evolved to include local spices, potatoes, and peas. Today, samosas are beloved across South Asia, the Middle East, and Africa as the ultimate portable snack.' WHERE slug = 'samosa-bites-in';

UPDATE recipes SET continent = 'Asia', history = 'Vegetable Pakoras are a beloved Indian street food of spiced vegetables dipped in chickpea flour batter and deep-fried. The tradition of frying vegetables in batter dates back centuries in Indian cuisine. Pakoras are especially popular during the monsoon season and are an essential part of Indian tea-time culture.' WHERE slug = 'vegetable-pakoras-in';

UPDATE recipes SET continent = 'Asia', history = 'Italian Bruschetta originated in ancient Rome where olive oil was tested on grilled bread rubbed with garlic. The word comes from the Roman dialect "bruscare" meaning "to roast over coals." This simple antipasto has been a cornerstone of Italian cuisine for centuries, celebrating the quality of olive oil and tomatoes.' WHERE slug = 'italian-bruschetta-it';

UPDATE recipes SET continent = 'Europe', history = 'Italian Bruschetta originated in ancient Rome where olive oil was tested on grilled bread rubbed with garlic. The word comes from the Roman dialect "bruscare" meaning "to roast over coals." This simple antipasto has been a cornerstone of Italian cuisine for centuries, celebrating the quality of olive oil and tomatoes.' WHERE slug = 'italian-bruschetta-it';

UPDATE recipes SET continent = 'Asia', history = 'Gyoza are Japanese dumplings adapted from Chinese jiaozi, introduced to Japan by soldiers returning from Manchuria after World War II. Japanese versions feature thinner wrappers, more garlic, and are typically pan-fried (yaki-gyoza) for a crispy bottom. They''ve become one of Japan''s most popular comfort foods.' WHERE slug = 'gyoza-jp';

UPDATE recipes SET continent = 'Asia', history = 'Teriyaki Chicken Wings showcase the Japanese teriyaki cooking technique, where meat is grilled or broiled with a glaze of soy sauce, mirin, and sugar. The word "teriyaki" combines "teri" (luster) and "yaki" (grilling). This technique dates back to the Edo period (1603-1868) and has become globally popular.' WHERE slug = 'teriyaki-chicken-wings-jp';

UPDATE recipes SET continent = 'Asia', history = 'Edamame (young soybeans) have been consumed in Japan for over 2,000 years, with the first recorded mention in the year 1275. The name means "stem beans" in Japanese. Once a simple farmhouse snack, edamame became a global health food phenomenon in the early 2000s, prized for their protein content.' WHERE slug = 'edamame-jp';

UPDATE recipes SET continent = 'Asia', history = 'Miso Soup is a foundational element of Japanese cuisine, consumed daily by millions. Miso paste, made from fermented soybeans, was introduced to Japan from China around the 7th century. By the Muromachi period (1336-1573), miso soup had become central to the Japanese meal structure.' WHERE slug = 'miso-soup-jp';

UPDATE recipes SET continent = 'Asia', history = 'Onigiri (rice balls) are one of Japan''s oldest portable foods, dating back over 2,000 years. The earliest mention appears in the 11th century diary "Murasaki Shikibu Nikki." Wrapped in nori seaweed and filled with umeboshi, salmon, or tuna mayo, onigiri remain Japan''s most popular convenience store food.' WHERE slug = 'onigiri-jp';

UPDATE recipes SET continent = 'Asia', history = 'Korean BBQ Short Ribs (Galbi) represent Korea''s beloved barbecue tradition. The practice of grilling marinated meat dates back to the Goguryeo Kingdom (37 BCE-668 CE). The sweet soy sauce and sesame marinade that defines galbi evolved during the Joseon Dynasty, making it one of Korea''s most prized meat dishes.' WHERE slug = 'korean-bbq-short-ribs-kr';

UPDATE recipes SET continent = 'Asia', history = 'Korean Fried Chicken (Chikin) became a cultural phenomenon in South Korea in the late 1970s and exploded in popularity during the 2002 World Cup. The double-frying technique creates an ultra-crispy coating. Korean fried chicken, paired with beer ("chimaek"), has become one of Korea''s most successful culinary exports.' WHERE slug = 'korean-fried-chicken-kr';

UPDATE recipes SET continent = 'Asia', history = 'Kimchi Fried Rice (Kimchi Bokkeumbap) is a beloved Korean comfort food that transforms aged, fermented kimchi into a satisfying fried rice dish. This ingenious use of mature kimchi reflects the Korean philosophy of zero waste and the central role of kimchi in Korean daily life for over 2,000 years.' WHERE slug = 'kimchi-fried-rice-kr';

UPDATE recipes SET continent = 'Asia', history = 'Tteokbokki (spicy rice cakes) is one of Korea''s most iconic street foods. Originally a royal court dish during the Joseon Dynasty made with soy sauce, the modern spicy gochujang version emerged in the 1950s post-Korean War era. It has since become synonymous with Korean street food culture and K-drama snacking.' WHERE slug = 'tteokbokki-kr';

UPDATE recipes SET continent = 'Asia', history = 'Bibimbap Bowls are one of Korea''s most iconic dishes, meaning "mixed rice." The dish dates back to the Joseon Dynasty and was traditionally served on the eve of Lunar New Year to use up remaining side dishes. Jeonju bibimbap is considered the definitive version and was designated a Korean cultural heritage food.' WHERE slug = 'bibimbap-bowls-kr';

UPDATE recipes SET continent = 'Asia', history = 'Malaysian Laksa is a spicy noodle soup that represents Malaysia''s multicultural identity, blending Malay, Chinese, and Indian flavors. The Peranakan (Nyonya) community is credited with creating this fusion dish. Laksa was voted the 7th most delicious food in the world by CNN Travel.' WHERE slug = 'malaysian-laksa-my';

UPDATE recipes SET continent = 'Asia', history = 'Pad Thai was created in the 1930s-1940s during a nationalistic campaign by Thai Prime Minister Plaek Phibunsongkhram to promote Thai identity. Despite its relatively recent invention, pad thai quickly became Thailand''s most famous dish globally, representing the perfect balance of sweet, sour, salty, and spicy.' WHERE slug = 'pad-thai-th';

UPDATE recipes SET continent = 'Asia', history = 'Thai Spring Rolls are a lighter, fresh version of the Chinese-origin spring roll, reflecting Thailand''s adaptation of Chinese culinary traditions. Thai versions emphasize fresh herbs, rice paper wrappers, and dipping sauces with fish sauce, lime, and chili—the hallmarks of Thai flavor balance.' WHERE slug = 'thai-spring-rolls-th';

UPDATE recipes SET continent = 'Asia', history = 'Thai Basil Stir Fry (Pad Krapao) is Thailand''s most popular street food, made with holy basil, meat, and chili. Served over rice with a fried egg, it''s the quintessential Thai lunch. Holy basil (krapao) is sacred in Thai Buddhist tradition and adds a distinctive peppery, anise-like flavor.' WHERE slug = 'thai-basil-stir-fry-th';

UPDATE recipes SET continent = 'Asia', history = 'Vietnamese Summer Rolls (Gỏi Cuốn) are a fresh, healthy Vietnamese classic that showcases the country''s love of fresh herbs and rice paper. Unlike fried spring rolls, these translucent rolls emphasize raw vegetables and herbs, reflecting Vietnam''s philosophy of balanced, light eating that dates back centuries.' WHERE slug = 'vietnamese-summer-rolls-vn';
